x-codeSamples.source:
curl -X POST "https://api.ionq.co/v0.4/jobs" \
  -H "Authorization: apiKey your-api-key" \
  -H "Content-Type: application/json" \
  -d '{
    "type" : "ionq.circuit.v1",
    "name": "Sample circuit",
    "metadata": {
      "fizz": "buzz",
      "foo": "bar"
    },
    "shots": 500,
    "backend": "qpu.forte-1",
    "settings" :
    {
      "error_mitigation":
      {
        "debiasing": false
      }
    },
    "input": {
      "qubits":  2,
      "gateset": "qis",
      "circuit": [
      {
        "gate": "h",
        "target": 0
      }
      ]
    }
  }'

curl -X POST "https://api.ionq.co/v0.4/jobs" \
  -H "Authorization: apiKey your-api-key" \
  -H "Content-Type: application/json" \
  -d '{
    "type": "ionq.multi-circuit.v1",
    "backend": "simulator",
    "shots": 500,
    "input": {
      "gateset": "native",
      "qubits": 2,
      "circuits": [
        {
          "name": "qis circuit override",
          "gateset": "qis",
          "circuit": [
            {
              "gate": "h",
              "target": 0
            },
            {
              "gate": "cnot",
              "target": 0,
              "control": 1
            }
          ]
        },
        {
          "name": "native circuit from parent",
          "circuit": [
            {
              "gate": "ms",
              "targets": [0, 1],
              "phases": [0, 0.25]
            },
            {
              "gate": "gpi2",
              "target": 0,
              "phase": 0.75
            }
          ]
        }
      ]
    }
  }'

curl -X POST "https://api.ionq.co/v0.4/jobs" \
  -H "Authorization: apiKey your-api-key" \
  -H "Content-Type: application/json" \
  -d '{
    "type": "ionq.qasm3.v1",
    "name": "circuit qasm3",
    "backend": "qpu.forte-1",
    "shots": 500,
    "input": {
      "data": "OPENQASM 3.0;include \"stdgates.inc\";qubit[2] q;bit[2] c;h q[0];cx q[0], q[1];c[0] = measure q[0];c[1] = measure q[1];"
    }
  }'

curl -X POST "https://api.ionq.co/v0.4/jobs/617a1f8b-59d4-435d-aa33-695433d7155e/clone" \
  -H "Authorization: apiKey your-api-key" \
  -H "Content-Type: application/json" \
  -d '{
    "name": "cloned-job",
    "shots": 500,
    "backend": "qpu.forte-1",
    "settings": {
      "error_mitigation": {
        "debiasing": true
      }
    },
    "dry_run": false
  }'

curl -X POST "https://api.ionq.co/v0.4/jobs/617a1f8b-59d4-435d-aa33-695433d7155e/move" \
  -H "Authorization: apiKey your-api-key" \
  -H "Content-Type: application/json" \
  -d '{
    "name": "moved-job",
    "shots": 500,
    "backend": "qpu.forte-1",
    "settings": {
      "error_mitigation": {
        "debiasing": true
      }
    },
    "dry_run": false
  }'

example.data:
OPENQASM 3.0;
include "stdgates.inc";
qubit[2] q;
bit[2] c;
h q[0];
cx q[0], q[1];
c[0] = measure q[0];
c[1] = measure q[1];

IonqQasm3V1.example:
OPENQASM 3.0;
qubit[2] q;
bit[2] c;
h q[0];
cx q[0], q[1];
c[0] = measure q[0];
c[1] = measure q[1];
